//! Haiku and Luna [`JudgeBackend`] implementations.
//!
//! Both backends validate byte and token limits, count tokens, then send the
//! judge message. `validate_for_send` applies those limits before any HTTP
//! call. The provider count is checked again before the judge message is
//! posted (ADR-SAG-0004). The count request uses the same body as the judge
//! call except Haiku omits `max_tokens`.
//!
//! The two public types are generated by one private macro over the shared
//! [`Client`], so they cannot drift apart.

use std::fmt;
use std::sync::Arc;
use std::time::Duration;

use std::collections::BTreeMap;

use sc_agent_types::{
    BackendId, JevError, JudgeBackend, JudgeOutcome, JudgeRequest, NetworkErrorKind,
    QuestionAnswer, QuestionId, ResolvedApiKey,
};

use crate::retry::{self, RetrySleeper, ThreadSleeper};
use crate::retry_policy::{self, RetryBudget};
use crate::transport::{
    AuthScheme, BackendTransport, DEFAULT_CONNECT_TIMEOUT, DEFAULT_REQUEST_TIMEOUT, HttpRequest,
    HttpResponse,
};
use crate::validate::{self, ParsedQuestion};
use crate::wire::{self, ProviderKind};

#[derive(Clone)]
struct Provider {
    id: BackendId,
    name: &'static str,
    model: &'static str,
    host: &'static str,
    message_path: &'static str,
    count_path: &'static str,
    kind: ProviderKind,
}

impl Provider {
    fn haiku() -> Self {
        Self {
            id: BackendId::AnthropicHaiku,
            name: "haiku",
            model: wire::HAIKU_MODEL,
            host: wire::ANTHROPIC_HOST,
            message_path: wire::HAIKU_MESSAGE_PATH,
            count_path: wire::HAIKU_COUNT_PATH,
            kind: ProviderKind::Anthropic,
        }
    }

    fn luna() -> Self {
        Self {
            id: BackendId::OpenAiLuna,
            name: "luna",
            model: wire::LUNA_MODEL,
            host: wire::OPENAI_HOST,
            message_path: wire::LUNA_MESSAGE_PATH,
            count_path: wire::LUNA_COUNT_PATH,
            kind: ProviderKind::OpenAi,
        }
    }
}

struct Prepared {
    questions: Vec<ParsedQuestion>,
    message_body: Vec<u8>,
    count_body: Vec<u8>,
}

/// Converts the normalized answer object into typed answers.
///
/// A confidence or probability outside `[0, 1]` is `RESPONSE_INVALID`.
fn typed_answers(
    normalized: serde_json::Value,
) -> Result<BTreeMap<QuestionId, QuestionAnswer>, JevError> {
    let serde_json::Value::Object(map) = normalized else {
        return Err(JevError::response_invalid("LLM answers are not an object"));
    };
    map.into_iter()
        .map(|(id, answer)| {
            let question = QuestionId::try_from(id.as_str()).map_err(|_| {
                JevError::response_invalid(format!("answer id {id:?} is not valid"))
            })?;
            let answer: QuestionAnswer = serde_json::from_value(answer).map_err(|error| {
                JevError::response_invalid(format!("answer {id} is invalid: {error}"))
            })?;
            Ok((question, answer))
        })
        .collect()
}

#[derive(Clone)]
struct Client {
    provider: Provider,
    api_key: ResolvedApiKey,
    transport: Arc<dyn BackendTransport>,
    sleeper: Arc<dyn RetrySleeper>,
    connect_timeout: Duration,
    request_timeout: Duration,
}

impl Client {
    fn new(
        provider: Provider,
        api_key: ResolvedApiKey,
        transport: Arc<dyn BackendTransport>,
    ) -> Self {
        Self {
            provider,
            api_key,
            transport,
            sleeper: Arc::new(ThreadSleeper),
            connect_timeout: DEFAULT_CONNECT_TIMEOUT,
            request_timeout: DEFAULT_REQUEST_TIMEOUT,
        }
    }

    /// Builds both bodies and applies every pre-send limit.
    fn prepare_checked(&self, request: &JudgeRequest) -> Result<Prepared, JevError> {
        let prepared = self.prepare(request)?;
        validate::enforce_count_and_message_limits(
            self.provider.id.descriptor().request_limit_bytes(),
            &prepared.count_body,
            &prepared.message_body,
        )?;
        Ok(prepared)
    }

    fn validate_for_send(&self, request: &JudgeRequest) -> Result<(), JevError> {
        self.prepare_checked(request).map(|_| ())
    }

    fn judge(&self, request: &JudgeRequest) -> Result<JudgeOutcome, JevError> {
        let prepared = self.prepare_checked(request)?;
        let counted = self.send(self.provider.count_path, &prepared.count_body)?;
        let prompt_tokens = wire::parse_count(self.provider.name, &counted.body)?;
        validate::enforce_input_token_limit(prompt_tokens)?;
        let judged = self.send(self.provider.message_path, &prepared.message_body)?;
        let reply = wire::parse_vendor(self.provider.kind, self.provider.name, &judged.body)?;
        if let Some(reason) = &reply.truncation {
            return Err(JevError::response_invalid(reason.clone()));
        }
        let answers = typed_answers(wire::parse_answers(&reply.text, &prepared.questions)?)?;
        Ok(
            JudgeOutcome::new(self.provider.id, request, answers)?.with_provider_meta(
                wire::provider_meta(&reply, self.provider.model, prompt_tokens),
            ),
        )
    }

    fn prepare(&self, request: &JudgeRequest) -> Result<Prepared, JevError> {
        let prompt = request
            .llm()
            .ok_or_else(|| JevError::input_invalid("LLM system prompt is required"))?;
        let payload_text = std::str::from_utf8(request.payload().bytes())
            .map_err(|_| JevError::input_invalid("canonical payload is not UTF-8"))?;
        let questions = validate::validate_questions(request.payload().bytes())?;
        let message_body = wire::message_body(
            self.provider.kind,
            self.provider.model,
            payload_text,
            &prompt.system_prompt,
        );
        let count_body = wire::count_body(
            self.provider.kind,
            self.provider.model,
            payload_text,
            &prompt.system_prompt,
        );
        Ok(Prepared {
            questions,
            message_body,
            count_body,
        })
    }

    fn send(&self, path: &str, body: &[u8]) -> Result<HttpResponse, JevError> {
        let budget = RetryBudget::start();
        let mut sends = 0_u32;
        loop {
            sends += 1;
            let response = self
                .transport
                .send(self.http_request(path, body))
                .map_err(|error| self.api_key.redact_error(error))?;
            if response.status == 200 {
                return Ok(response);
            }
            if !retry_policy::is_busy(response.status) {
                return Err(self
                    .api_key
                    .redact_error(retry::http_failure(self.provider.name, &response)));
            }
            let wait = (sends < retry::BUSY_ATTEMPTS)
                .then(|| {
                    budget.next_wait(retry_policy::retry_after(retry::retry_after_header(
                        &response,
                    )))
                })
                .flatten();
            let Some(wait) = wait else {
                return Err(JevError::network(
                    NetworkErrorKind::Busy,
                    retry_policy::exhausted_detail(self.provider.name, response.status, sends),
                ));
            };
            self.sleeper.wait(wait);
        }
    }

    fn http_request(&self, path: &str, body: &[u8]) -> HttpRequest {
        HttpRequest {
            method: "POST".to_owned(),
            url: format!("https://{}{path}", self.provider.host),
            headers: wire::unsigned_headers(self.provider.kind),
            body: body.to_vec(),
            connect_timeout: self.connect_timeout,
            request_timeout: self.request_timeout,
            scheme: auth_scheme(self.provider.kind),
            credential: self.api_key.clone(),
            auth_installed: false,
        }
    }
}

fn auth_scheme(kind: ProviderKind) -> AuthScheme {
    match kind {
        ProviderKind::Anthropic => AuthScheme::AnthropicApiKey,
        ProviderKind::OpenAi => AuthScheme::Bearer,
    }
}

/// Generates one public backend type over [`Client`].
///
/// Both public types keep their own names, constructors, and docs; their
/// behavior is the shared client plus a [`Provider`] descriptor.
macro_rules! llm_backend {
    (
        $(#[$meta:meta])*
        $name:ident, $provider:expr, header = $header:literal
    ) => {
        $(#[$meta])*
        #[derive(Clone)]
        pub struct $name {
            client: Client,
        }

        impl $name {
            #[doc = concat!("Builds a ", stringify!($name), " with the default timeouts.")]
            ///
            /// `api_key` is the resolved credential, already normalized by
            /// [`ResolvedApiKey::try_new`]. This type does not read it.
            #[doc = concat!("[`BackendTransport::send`] installs the `", $header, "` header")]
            /// (ADR-SAG-0020).
            ///
            /// Construction is infallible: key validation happens once, in
            /// [`ResolvedApiKey::try_new`] (ADR-SAG-0020 r-1 amendment).
            #[must_use]
            pub fn new(api_key: ResolvedApiKey, transport: impl BackendTransport + 'static) -> Self {
                Self {
                    client: Client::new($provider, api_key, Arc::new(transport)),
                }
            }

            /// Creates the backend over [`UreqTransport`](crate::UreqTransport).
            ///
            /// The backend registry calls only this constructor, so the
            /// transport type can change without touching `sc-jev-check`.
            #[must_use]
            pub fn with_default_transport(api_key: ResolvedApiKey) -> Self {
                Self::new(api_key, crate::UreqTransport::new())
            }

            /// Replaces the wait used between busy retries of the same body.
            ///
            /// The default wait blocks the calling thread. Callers that must not block,
            /// including tests, pass their own [`RetrySleeper`].
            #[must_use]
            pub fn with_retry_sleeper(mut self, sleeper: impl RetrySleeper + 'static) -> Self {
                self.client.sleeper = Arc::new(sleeper);
                self
            }

            /// Replaces the connect and per-call request timeouts.
            ///
            /// The defaults are [`DEFAULT_CONNECT_TIMEOUT`] and
            /// [`DEFAULT_REQUEST_TIMEOUT`] (ADR-SAG-0007). Tests use this to
            /// shorten deadlines; every count and judge call carries the
            /// values on [`HttpRequest`].
            #[must_use]
            pub fn with_timeouts(mut self, connect: Duration, request: Duration) -> Self {
                self.client.connect_timeout = connect;
                self.client.request_timeout = request;
                self
            }
        }

        impl fmt::Debug for $name {
            fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
                formatter
                    .debug_struct(stringify!($name))
                    .field("model", &self.client.provider.model)
                    .field("host", &self.client.provider.host)
                    .finish_non_exhaustive()
            }
        }

        impl JudgeBackend for $name {
            fn id(&self) -> BackendId {
                self.client.provider.id
            }

            fn validate_for_send(&self, request: &JudgeRequest) -> Result<(), JevError> {
                self.client.validate_for_send(request)
            }

            fn judge(&self, request: &JudgeRequest) -> Result<JudgeOutcome, JevError> {
                self.client.judge(request)
            }
        }
    };
}

llm_backend! {
    /// API-direct Anthropic Haiku judge.
    ///
    /// # Examples
    ///
    /// ```
    /// use std::sync::Arc;
    ///
    /// use sc_agent_types::{
    ///     BackendKeyId, CanonicalJudgePayload, JevError, JudgeBackend, JudgeRequest,
    ///     LlmWireContext, NetworkErrorKind, PayloadBundle, ResolvedApiKey,
    /// };
    /// use sc_jev_backends::{
    ///     AnthropicHaikuBackend, BackendTransport, HttpRequest, HttpResponse,
    /// };
    ///
    /// struct Offline;
    ///
    /// impl BackendTransport for Offline {
    ///     fn send(&self, _request: HttpRequest) -> Result<HttpResponse, JevError> {
    ///         Err(JevError::network(NetworkErrorKind::Connect, "offline"))
    ///     }
    /// }
    ///
    /// let key = ResolvedApiKey::try_new(BackendKeyId::Anthropic, "test-key".to_owned())?;
    /// let backend = AnthropicHaikuBackend::new(key, Offline);
    /// let payload: CanonicalJudgePayload = serde_json::from_value(serde_json::json!({
    ///     "questions": [{"id": "q", "prompt": "Is it?", "choices": ["no", "yes"]}],
    ///     "state": []
    /// }))
    /// .expect("payload");
    /// let request = JudgeRequest::new(
    ///     Arc::new(PayloadBundle::encode(&payload)?),
    ///     Some(LlmWireContext::new("Judge.")),
    /// );
    /// backend.validate_for_send(&request)?;
    /// assert_eq!(backend.judge(&request).unwrap_err().code(), "NETWORK_ERROR");
    /// # Ok::<(), JevError>(())
    /// ```
    AnthropicHaikuBackend, Provider::haiku(), header = "x-api-key"
}

llm_backend! {
    /// API-direct OpenAI Luna judge.
    OpenAiLunaBackend, Provider::luna(), header = "Authorization"
}
